// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testFuzz_property(address newOwner, address pendingOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(pendingOwner != address(0));
        vm.assume(newOwner != pendingOwner);
        vm.prank(address(c));

        address currentOwner = c.owner();
        vm.assume(newOwner != address(0));
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();
        vm.prank(newOwner);
        bool success;
        try c.pause() { success = true; } catch { success = false; }
        assertTrue(success);
    }
}
